    const hubGeometry = new THREE.CylinderGeometry(hubRadius, hubRadius, hubWidth, 32);
    const hubMesh = new THREE.Mesh(hubGeometry);
    hubMesh.name = 'central_hub';
    hubMesh.rotation.z = Math.PI / 2; // Orient along X-axis
