import fs from 'fs';
import path from 'path';

// Initialize scene
const root = createScene();
const exporter = new OBJExporter();

const outputDir = '/root/output';
const partsDir = path.join(outputDir, 'part_meshes');
const linksDir = path.join(outputDir, 'links');

// Create directories
if (!fs.existsSync(partsDir)) fs.mkdirSync(partsDir, { recursive: true });
if (!fs.existsSync(linksDir)) fs.mkdirSync(linksDir, { recursive: true });

// Function to export a single object (Mesh or Group) to OBJ
function exportToOBJ(object, filepath) {
    const result = exporter.parse(object);
    fs.writeFileSync(filepath, result);
    console.log(`Exported: ${filepath}`);
}

// Traverse the scene to find parts
const parts = [];

